query SearchItinerary($input: SearchItineraryInput!) {
  searchItinerary(input: $input) {
    ... on SearchItinerarySuccessResult {
      __typename
      routes {
        routeDistance {
          value
          unit
        }
        duration
      }
    }
    ... on SearchItineraryNotFoundResult {
      message
    }
    __typename
  }
}
